import {openStudioDb,transact,requestResult} from '../../src/infrastructure/storage/database';
import {saveDraft} from '../../src/features/prompt-generation/draft-repository';
import {f} from '../helpers/fixtures';
export async function seedPromptWorkspace(){const db=await openStudioDb();try{await transact(db,db.tables.slice(),'readwrite',tx=>{for(const table of db.tables)tx.objectStore(table).clear();tx.objectStore('projects').put(f.project({title:'提示词源项目'}));tx.objectStore('graphs').put(f.graph({nodes:[{id:'text-1',type:'text',title:'原始需求',x:40,y:40,locked:false,data:{kind:'text',text:'康济健葆，1位人物，不切镜，5秒、9:16',referenceTokens:[]}}]}));});const result=await saveDraft(f.draft({revision:0,sceneId:'product',userRequest:'康济健葆，1位人物，不切镜，5秒、9:16',requestedSpec:{durationSeconds:5,ratio:'9:16'},sourceProjectId:'p1',sourceNodeId:'text-1',sourceRevision:1}),0,{db});if(result.status!=='saved')throw new Error('seed_draft_failed');}finally{db.close();}}
export async function promptWorkspaceState(){const db=await openStudioDb();try{return transact(db,['promptDrafts','promptRuns','runs'],'readonly',async tx=>({drafts:await requestResult(tx.objectStore('promptDrafts').getAll()),promptRuns:await requestResult(tx.objectStore('promptRuns').getAll()),runs:await requestResult(tx.objectStore('runs').getAll())}));}finally{db.close();}}
